import React from 'react'
import { connect } from 'react-redux'
import { 
  Select,
  Spin,
  Button,
  Row,
  Col,
  Card,
  Form,
  Alert,
  Table,
  Icon,
  DatePicker,
  notification 
} from 'antd'
import feedbackActions from '../../redux/feedback/actions'
import { FeedbackDashboardStyle } from './index.style'
import errorActions from '../../../redux/error/actions'
import moment from 'moment'
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  Cell
} from 'recharts'
import StarRatings from 'react-star-ratings'

const { getFeedbackDashboard, getProduct, getFeedbackTable, resetStateFeedback, downloadFeedbackReport } = feedbackActions
const { RangePicker } = DatePicker
const { Option } = Select
const { resetErrorRedux } = errorActions

const rating = [
  { 'name': 'All Rating', 'value': 'all' },
  { 'name': 'Rating 1', 'value': '1' },
  { 'name': 'Rating 2', 'value': '2' },
  { 'name': 'Rating 3', 'value': '3' },
  { 'name': 'Rating 4', 'value': '4' },
  { 'name': 'Rating 5', 'value': '5' }
]

const settleColors = ['#baf9d2', '#83e7ac', '#54b47a', '#3b945f', '#26633f']
const rejectColors = ['#f6c6f4', '#f18bed', '#cc64c8', '#8e3d8b', '#552253']
class FeedbackForm extends React.Component {
  constructor(props) {
    super(props)
    this.state = {
      modalData: {},
      startDate: moment().subtract(1, 'week').format('YYYY-MM-DD'),
      endDate: moment().format('YYYY-MM-DD'),
      productKey: 'all',
      rating: 'all',
      showDashboard: true,
      dataTableState: 'settled'
    }
  }

  componentDidMount = () => {
    const payload = {
      start_date: this.state.startDate,
      end_date: this.state.endDate
    }
    this.props.resetStateFeedback()
    this.props.getProduct()
    this.props.getFeedbackDashboard(payload)
  };

  static getDerivedStateFromProps = (props) => {
    const { downloadFeedbackLoading, downloadFeedbackError, downloadFeedbackMessage, resetErrorRedux, resetStateFeedback } = props
 
    if(!downloadFeedbackLoading && downloadFeedbackMessage) {
      notification[downloadFeedbackError ? 'error' : 'success']({ message: downloadFeedbackMessage })
      downloadFeedbackError && resetErrorRedux(['DOWNLOAD_FEEDBACK_REPORT'])
      resetStateFeedback(['downloadFeedbackMessage'])
    }
  }
  onChangeDatePicker = (_, dateString) => {
    this.setState({
      startDate: dateString[0],
      endDate: dateString[1]
    })
  }

  handleChangeProduct = (value) => {
    this.setState({
      productKey: value
    })
  }

  handleChangeRating = (value) => {
    this.setState({
      rating: value
    })
  }

  constructChartData = (data) => {
    let array = []
    for (var i = 1; i <= 5; i++) {
      let val = (!!data && data[i]) || 0
      array.push({ 'name': i, 'Rating count': val })
    }
    return array
  }

  submitChart = () => {
    const { showDashboard, dataTableState } = this.state
    if (showDashboard) {
      this.getDashboardData()
    } else {
      this.getTableData(dataTableState)
    }
  }

  downloadReport = () => {
    const { startDate, endDate, productKey, rating } = this.state
    const payload = {
      start_date: startDate,
      end_date: endDate
    }
    if(productKey !== 'all') {
      payload['partnerproduct_id'] = productKey
    }
    if(rating !== 'all') {
      payload['rating'] = rating
    }
    
    this.props.downloadFeedbackReport(payload)
  }

  getDashboardData = () => {
    const payload = {
      start_date: this.state.startDate,
      end_date: this.state.endDate,
      partnerproduct_id: this.state.productKey,
      rating: this.state.rating
    }
    this.props.getFeedbackDashboard(payload)
  }

  getTableData = (value) => {
    const payload = {
      start_date: this.state.startDate,
      end_date: this.state.endDate,
      partnerproduct_id: this.state.productKey,
      rating: this.state.rating,
      event: value
    }
    this.setState({
      showDashboard: false,
      dataTableState: value
    })
    this.props.getFeedbackTable(payload)
  }

  goToDashboard = () => {
    this.setState({
      showDashboard: true
    })
    this.getDashboardData()
  }

  renderTotalBox = () => {
    const { feedbackDashboardData } = this.props
    return (
      <Col sm={24}>
        <Row className='feedback-total-row' type='flex'>
          <Col sm={6}>
            <Card className='total-claim'>
              <h1>
                {feedbackDashboardData.total_claims_count || 0}
              </h1>
              <div>Total Claims</div>
            </Card>
          </Col>
          <Col sm={6}>
            <Card className='total-settled' onClick={() => { this.getTableData('settled') }}>
              <h1>
                {feedbackDashboardData.total_claim_settled_feedback_count || 0}
              </h1>
              <div>
                Total Feedback from <br />
                settled claims
              </div>
            </Card>
          </Col>
          <Col sm={6}>
            <Card className='total-rejected' onClick={() => { this.getTableData('rejected') }}>
              <h1>
                {feedbackDashboardData.total_claim_rejected_feedback_count || 0}
              </h1>
              <div>
                Total Feedback from <br />
                rejected claims
              </div>
            </Card>
          </Col>
          <Col sm={6}>
            <Card className='total-feedback' onClick={() => { this.getTableData('') }}>
              <h1>
                {
                  (feedbackDashboardData.total_claim_settled_feedback_count || 0) +
                  (feedbackDashboardData.total_claim_rejected_feedback_count || 0)
                }
              </h1>
              <div>Total Feedback</div>
            </Card>
          </Col>
        </Row>
      </Col>
    )
  }

  renderLegend = (value) => {
    let colors = settleColors
    if (value === 'reject') {
      colors = rejectColors
    }
    return (
      <div className='legend-chart'>
        {
          [1, 2, 3, 4, 5].map((val, index) => {
            return (
              <div key={index}>
                <div className='legend-color' style={{ backgroundColor: colors[index] }} />
                <span>Rating #{val}</span>
              </div>
            )
          })
        }
      </div>
    )
  }

  renderChart = () => {
    const { feedbackDashboardData } = this.props
    const settledData = this.constructChartData(feedbackDashboardData.claim_settled_rating_data)
    const rejectData = this.constructChartData(feedbackDashboardData.claim_rejected_rating_data)

    let totalSettleFeedback = 0
    let tempSettleTotal = 0
    settledData.forEach(val => {
      totalSettleFeedback += val['Rating count']

      tempSettleTotal += val.name * val['Rating count']
    })
    const settledAverage = totalSettleFeedback === 0 ? 0 : tempSettleTotal / totalSettleFeedback

    let totalRejectFeedback = 0
    let tempRejectTotal = 0
    rejectData.forEach(val => {
      totalRejectFeedback += val['Rating count']
      tempRejectTotal += val.name * val['Rating count']
    })
    const rejectAverage = totalRejectFeedback === 0 ? 0 : tempRejectTotal / totalRejectFeedback

    return (
      <Col sm={24}>
        <Row className='feedback-padding'>
          <Col sm={12}>
            <Card>
              <span className='chart-title'>
                SETTLED CLAIMS
              </span>
              <center>
                <BarChart width={450} height={400} data={settledData}>
                  <CartesianGrid strokeDasharray='3 3' />
                  <XAxis dataKey='name' />
                  <YAxis />
                  <Tooltip />
                  <Legend align='right' verticalAlign='top' content={this.renderLegend('settle')} />
                  <Bar dataKey='Rating count' fill='#8884d8'>
                    {
                      settledData.map((_, index) => (
                        <Cell key={`cell-${index}`} fill={settleColors[index]} />
                      ))
                    }
                  </Bar>
                </BarChart>
              </center>
            </Card>
          </Col>
          <Col sm={12}>
            <Card>
              <span className='chart-title'>
                REJECTED CLAIMS
              </span>
              <center>
                <BarChart width={450} height={400} data={rejectData}>
                  <CartesianGrid strokeDasharray='3 3' />
                  <XAxis dataKey='name' />
                  <YAxis />
                  <Tooltip />
                  <Legend align='right' verticalAlign='top' content={this.renderLegend('reject')} />
                  <Bar dataKey='Rating count' fill='#8884d8'>
                    {
                      settledData.map((_, index) => (
                        <Cell key={`cell-${index}`} fill={rejectColors[index]} />
                      ))
                    }
                  </Bar>
                </BarChart>
              </center>
            </Card>
          </Col>
        </Row>
        <Row className='feedback-padding bottom-page'>
          <Col sm={12}>
            <Card className='feedback-average'>
              Average
              <StarRatings
                rating={settledAverage}
                starRatedColor='#3b935f'
                starDimension='30px'
                numberOfStars={5}
                name='rating'
              />
              {settledAverage.toFixed(2)}
            </Card>
          </Col>
          <Col sm={12}>
            <Card className='feedback-average'>
              Average
              <StarRatings
                rating={rejectAverage}
                starRatedColor='#cb67ca'
                starDimension='30px'
                numberOfStars={5}
                name='rating'
              />
              {rejectAverage.toFixed(2)}
            </Card>
          </Col>
        </Row>
      </Col>
    )
  }

  renderTable = () => {
    const {
      feedbackTableData,
      getFeedbackTableLoading
    } = this.props
    let tableData = feedbackTableData.claim_feedback_list || []
    const columns = [
      {
        key: 'claim_number',
        title: (
          <div className='table-title'>
            <span>
              Action
            </span>
          </div>
        ),
        render: (val, record) => {
          return (
            <a href={'/claims/' + record.claim_id}>
              {val}
            </a>
          )
        },
        dataIndex: 'claim_number'
      },
      {
        key: 'rating',
        title: (
          <div className='table-title'>
            <span>
              Rating
            </span>
          </div>
        ),
        dataIndex: 'rating'
      }, {
        key: 'feedback_data',
        title: (
          <div className='table-title'>
            <span>
              Feedback
            </span>
          </div>
        ),
        render: (val) => {
          const selectedFeedback = val.options.filter(val => {
            return val.is_selected
          }).map(val => {
            return val.label
          }).join(', ')
          return (
            <span>
              {selectedFeedback}
            </span>
          )
        },
        dataIndex: 'feedback_data'
      }, {
        key: 'review',
        title: (
          <div className='table-title'>
            <span>
              Comment
            </span>
          </div>
        ),
        dataIndex: 'review'
      }
    ]
    return (
      <Col className='feedback-table' sm={24}>
        <Card bordered={false}>
          <Table
            columns={columns}
            rowKey={(_, index) => index}
            dataSource={tableData}
            loading={getFeedbackTableLoading}
            scroll={{ x: true }}
            pagination={false}
            bordered
          />
        </Card>
      </Col>
    )
  };

  render() {
    const {
      startDate,
      endDate,
      showDashboard
    } = this.state
    const {
      productData,
      getFeedbackLoading,
      getProductLoading,
      getFeedbackTableLoading
    } = this.props
    const loading = !!getFeedbackLoading || !!getProductLoading || !!getFeedbackTableLoading

    return (
      <FeedbackDashboardStyle>
        {false && (
          <Alert message={'searchMessage'} type='error' />
        )}
        <Spin spinning={loading} tip='Fetching data...'>
          <Row className='feedback-row'>
            {!showDashboard && (
              <Col sm={24}>
                <Row className='feedback-padding'>
                  <Col className='feedback-detail-header' sm={24}>
                    <span onClick={this.goToDashboard}>
                      <Icon type='arrow-left' />
                      Feedback Dashboard
                    </span>
                  </Col>
                </Row>
              </Col>
            )
            }
            <Col sm={24}>
              <Row className='feedback-padding'>
                <Col md={24} lg={8}>
                  <RangePicker
                    allowClear={false}
                    separator='to'
                    defaultValue={[moment(startDate, 'YYYY-MM-DD'), moment(endDate, 'YYYY-MM-DD')]}
                    onChange={this.onChangeDatePicker}
                  />
                </Col>
                <Col lg={4}>
                  <Select
                    className='feedback-dropdown'
                    onChange={this.handleChangeProduct}
                    placeholder='Select product'
                    dropdownMatchSelectWidth={false}
                    defaultValue='all'
                  >
                    <Option value='all'>All products</Option>
                    {productData.map((option, index) =>
                      <Option key={index} value={option.id}>{option.display_name}</Option>
                    )}
                  </Select>
                </Col>
                <Col lg={4}>
                  <Select
                    className='feedback-dropdown'
                    onChange={this.handleChangeRating}
                    placeholder='Select rating'
                    dropdownMatchSelectWidth={false}
                    defaultValue='all'
                  >
                    {rating.map((option, index) =>
                      <Option key={index} value={option.value}>{option.name}</Option>
                    )}
                  </Select>
                </Col>
                <Col lg={4}>
                  <Button type='primary' onClick={this.submitChart}>
                    {loading ? 'Please wait ...' : 'Submit'}
                  </Button>
                </Col>
                <Col lg={4}>
                  <Button type='primary' onClick={this.downloadReport}>
                    Download Report
                  </Button>
                </Col>
              </Row>
            </Col>
            {showDashboard ? ([
              this.renderTotalBox(),
              this.renderChart()
            ])
              : this.renderTable()
            }
          </Row>
        </Spin>
      </FeedbackDashboardStyle>
    )
  }
}

const WrappedForm = Form.create({})(FeedbackForm)

export default connect(
  state => ({
    feedbackDashboardData: state.Feedback.feedbackDashboardData,
    getFeedbackLoading: state.Loading.GET_FEEDBACK_DASHBOARD,
    getFeedbackError: state.Error.GET_FEEDBACK_DASHBOARD,
    feedbackDashboardMessage: state.Feedback.feedbackDashboardMessage,

    productData: state.Feedback.productData,
    productMessage: state.Feedback.productMessage,
    getProductLoading: state.Loading.GET_PRODUCT,
    getProductError: state.Error.GET_PRODUCT,

    feedbackTableData: state.Feedback.feedbackTableData,
    getFeedbackTableLoading: state.Loading.GET_FEEDBACK_TABLE,
    getFeedbackTableError: state.Error.GET_FEEDBACK_TABLE,
    feedbackTableMessage: state.Feedback.feedbackTableMessage,
    downloadFeedbackLoading: state.Loading.DOWNLOAD_FEEDBACK_REPORT,
    downloadFeedbackError: state.Error.DOWNLOAD_FEEDBACK_REPORT,
    downloadFeedbackMessage: state.Feedback.downloadFeedbackMessage
  }),
  { 
    getFeedbackDashboard,
    getProduct,
    getFeedbackTable,
    resetStateFeedback,
    downloadFeedbackReport,
    resetErrorRedux 
  }
)(WrappedForm)
